:root{
  --bg:#0c0f14;
  --panel:#141922;
  --panel2:#1a2130;
  --edge:#243044;
  --edge2:#2d3a4f;
  --fg:#e9edf4;
  --mut:#98a3b7;
  --dim:#6b7689;
  --accent:#5fd3c4;
  --accent2:#8ab4ff;
  --up:#4fd08a;
  --down:#ff7a7a;
  --warn:#f2c14e;
  --radius:10px;
  --maxw:1440px;
  --num:"SFMono-Regular",ui-monospace,Menlo,Consolas,monospace;
}

*{box-sizing:border-box}
html,body{margin:0}

body{
  background:
    radial-gradient(1200px 600px at 80% -10%, #18223344 0%, transparent 60%),
    var(--bg);
  color:var(--fg);
  font:14px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  -webkit-font-smoothing:antialiased;
  padding-bottom:48px;
}

header{padding:22px 32px 0;max-width:var(--maxw);margin:0 auto}
.brand{font-size:20px;font-weight:650;letter-spacing:.2px;display:flex;align-items:center;gap:10px}
.mark{width:12px;height:12px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px #5fd3c422,0 0 14px #5fd3c4}
.tag{color:var(--mut);margin:6px 0 0;max-width:820px}
.meta{color:var(--dim);font-size:12px;margin-top:8px;font-family:var(--num)}
.meta span+span:before{content:"\00b7";margin:0 8px;color:#3a4457}

.tabs{display:flex;gap:4px;margin-top:16px;border-bottom:1px solid var(--edge)}
.tab,.back,.ghost,.toggle{
  font:inherit;font-size:13px;color:var(--mut);background:transparent;border:0;cursor:pointer;
  padding:9px 14px;border-radius:8px 8px 0 0
}
.tab:hover,.back:hover,.ghost:hover,.toggle:hover{color:var(--fg);background:#19202c}
.tab.on{color:var(--fg);background:var(--panel);box-shadow:inset 0 -2px 0 var(--accent)}
.toggle[aria-pressed=true]{color:var(--accent);background:#123a36;box-shadow:inset 0 0 0 1px var(--accent)}

main{max-width:var(--maxw);margin:0 auto;padding:20px 32px}
.view.hidden{display:none}

h2{font-size:17px;font-weight:620;letter-spacing:.1px;margin:22px 0 10px}
h2 span{font-size:12px;font-weight:500;color:var(--dim);margin-left:10px}
h3{font-size:13px;font-weight:600;margin:0 0 8px;letter-spacing:.3px}
.lead{color:var(--mut);margin:0 0 12px;max-width:900px}

.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:6px}
.stat{background:var(--panel);border:1px solid var(--edge);border-radius:var(--radius);padding:12px 14px}
.stat b{display:block;font:600 22px/1.15 var(--num);color:var(--fg)}
.stat span{color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.6px}
.stat.accent b{color:var(--accent)}

.controls{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0 10px;align-items:center}
.controls input[type=search],.controls select{
  font:inherit;font-size:13px;color:var(--fg);background:var(--panel);
  border:1px solid var(--edge2);border-radius:8px;padding:8px 10px
}
.controls input[type=search]{flex:1 1 260px}
.controls input:focus,.controls select:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px #5fd3c422}
.controls button{font:inherit;font-size:12px;padding:8px 12px;border:1px solid var(--edge2);border-radius:999px;color:var(--mut);background:transparent;cursor:pointer}
.controls button:hover{color:var(--fg);border-color:var(--accent)}

.line{color:var(--dim);font-size:12px;margin-bottom:8px;font-family:var(--num)}

.tablewrap{overflow:auto;border:1px solid var(--edge);border-radius:var(--radius);background:var(--panel)}
table{width:100%;border-collapse:collapse;font-size:13px}
thead th{
  position:sticky;top:0;z-index:1;background:#111721;color:var(--dim);font-weight:560;
  font-size:11px;text-transform:uppercase;letter-spacing:.55px;text-align:right;
  padding:9px 12px;border-bottom:1px solid var(--edge2);white-space:nowrap
}
thead th.left,tbody td.left{text-align:left}
tbody td{padding:8px 12px;border-bottom:1px solid #1b2331;text-align:right;white-space:nowrap;font-family:var(--num);font-variant-numeric:tabular-nums}
tbody td.name{font-family:inherit;text-align:left;white-space:normal}
tbody td.cat{font-family:inherit;text-align:left;color:var(--mut);white-space:normal;max-width:220px}
tbody td.chains{font-family:inherit;text-align:left;color:var(--dim);white-space:normal;max-width:260px}
tbody tr:last-child td{border-bottom:0}
tbody tr.rowlink{cursor:pointer}
tbody tr.rowlink:hover td{background:#17202c}

.rank{color:var(--dim)}
.cellname{font-weight:600}
.slug{color:var(--dim);font-size:11px;font-family:var(--num);display:block;margin-top:1px}
.up{color:var(--up)}
.down{color:var(--down)}
.flat{color:var(--dim)}
.pill{display:inline-block;padding:1px 8px;border-radius:999px;font-size:11px;font-family:inherit;border:1px solid var(--edge2);color:var(--mut)}
.pill.watch{color:var(--accent);border-color:#2a4d49;background:#11211f}
.chip{display:inline-block;padding:1px 7px;margin:1px 3px 1px 0;border-radius:6px;font-size:11px;background:#1b2331;color:var(--mut);font-family:inherit}
.implied{font-weight:640;color:var(--fg)}

.foot{color:var(--dim);font-size:12px;margin-top:14px}

.card{background:var(--panel);border:1px solid var(--edge);border-radius:var(--radius);padding:16px 18px}
.detail-head{display:flex;flex-wrap:wrap;gap:18px;align-items:flex-end;justify-content:space-between;margin-top:6px}
.detail-title{font-size:26px;font-weight:680;letter-spacing:.2px;margin:0}
.detail-title .rk{color:var(--dim);font-family:var(--num);font-weight:600;margin-right:10px;font-size:20px}
.detail-sub{color:var(--mut);margin:4px 0 0}
.bigval{text-align:right}
.bigval b{display:block;font:680 30px/1 var(--num);color:var(--accent)}
.bigval span{color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.7px}

.dgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:16px 0}
.dstat{background:var(--panel2);border:1px solid var(--edge);border-radius:8px;padding:10px 12px}
.dstat span{display:block;color:var(--dim);font-size:11px;text-transform:uppercase;letter-spacing:.5px}
.dstat b{display:block;font:600 16px/1.3 var(--num);margin-top:3px;color:var(--fg)}

.cols{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}
@media (max-width:1000px){
  .cols{grid-template-columns:1fr}
  .stats{grid-template-columns:repeat(2,minmax(0,1fr))}
}

.formula{background:#10151d;border:1px solid var(--edge);border-radius:8px;padding:14px 16px;font-family:var(--num);font-size:13px;line-height:1.7;color:var(--mut);overflow:auto}
.formula b{color:var(--fg)}
.formula .hl{color:var(--accent)}
.formula .eq{color:var(--accent2)}

.modeltable{width:100%}
.modeltable td{padding:9px 0;border-bottom:1px solid #1b2331;text-align:left;font-family:inherit;white-space:normal}
.modeltable td:last-child{text-align:right;font-family:var(--num);color:var(--fg)}
.modeltable tr:last-child td{border-bottom:0}
.modeltable .lbl{color:var(--mut)}
.modeltable .fn{color:var(--dim);font-size:11.5px;font-family:var(--num)}
.total td{font-weight:640;color:var(--accent)!important;border-top:1px solid var(--edge2)}

.peerbox{margin-top:10px}
.peerbox h4{margin:0 0 6px;font-size:11px;text-transform:uppercase;letter-spacing:.6px;color:var(--dim);font-weight:560}
.peerrow{display:flex;justify-content:space-between;gap:10px;padding:5px 0;border-bottom:1px dashed #1e2736;font-size:12.5px}
.peerrow:last-child{border-bottom:0}
.peerrow .n{color:var(--mut)}
.peerrow .m{font-family:var(--num);color:var(--fg)}
.peerrow.link{cursor:pointer}
.peerrow.link:hover .n{color:var(--accent)}

ol.steps{margin:8px 0 0;padding:0;counter-reset:step;list-style:none}
ol.steps li{position:relative;padding:10px 0 10px 40px;border-bottom:1px solid #1b2331;color:var(--fg);font-size:13px;line-height:1.5}
ol.steps li:last-child{border-bottom:0}
ol.steps li:before{
  counter-increment:step;content:counter(step);
  position:absolute;left:0;top:9px;width:26px;height:26px;border-radius:50%;
  background:#1b2331;color:var(--accent);
  display:flex;align-items:center;justify-content:center;font:600 12px/1 var(--num);border:1px solid var(--edge2)
}

.tabletick{color:var(--dim);font-size:12px}

.badge{display:inline-block;font-size:11px;font-family:var(--num);padding:2px 8px;border-radius:999px;border:1px solid var(--edge2);color:var(--mut);margin-left:8px;vertical-align:middle}
.badge.ok{color:var(--up);border-color:#1f4133;background:#0f1f18}
.badge.bad{color:var(--down);border-color:#4a2424;background:#1f1010}

pre.block{background:#10151d;border:1px solid var(--edge);border-radius:8px;padding:14px 16px;overflow:auto;font-family:var(--num);font-size:12px;line-height:1.6;color:var(--mut);margin:10px 0}
pre.block b{color:var(--fg)}
kbd{font-family:var(--num);font-size:11px;background:#1b2331;border:1px solid var(--edge2);border-radius:5px;padding:1px 6px;color:var(--fg)}
.muted{color:var(--dim)}
```

